  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "audífonos para viajar cancelación ruido inalámbrico",
        "category": "audifonos",
        "max_price": 228990,
        "attributes": {
          "cancelacion_ruido": true,
          "inalambrico": true
